import inspect
from functools import wraps, partial
import asyncio
from fastapi.dependencies.models import Dependant

def iscoroutinefunction(func):
    return inspect.iscoroutinefunction(func)

def test_is_coroutine_callable():
    async def async_func():
        return 1

    def sync_func():
        return 1

    def wrap(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapper

    async def async_wrap(f):
        @wraps(f)
        async def wrapper(*args, **kwargs):
            return await f(*args, **kwargs)
        return wrapper

    test_cases = [
        ("regular async", async_func, True),
        ("regular sync", sync_func, False),
        ("wrapped async", wrap(async_func), True),
        ("async wrapped sync", async_wrap(sync_func), True),
        ("partial async", partial(async_func), True),
        ("partial wrapped async", partial(wrap(async_func)), True),
        ("wrapped partial async", wrap(partial(async_func)), True),
        ("partial async wrapped sync", partial(async_wrap(sync_func)), True),
        ("async wrapped partial async", async_wrap(partial(async_func)), True),
    ]

    for name, call, expected in test_cases:
        dep = Dependant(call=call)
        result = dep.is_coroutine_callable
        print(f"{name}: expected {expected}, got {result}")
        assert result == expected, f"{name} failed"

if __name__ == "__main__":
    try:
        test_is_coroutine_callable()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

