import os
import sys

class ProxyFile:
    def __init__(self, file):
        self.file = file
    def write(self, data):
        self.file.write(data)
    def fileno(self):
        return self.file.fileno()
    def flush(self):
        self.file.flush()

def test_proxy_isatty():
    # Use sys.stdout as the underlying file
    proxy = ProxyFile(sys.stdout)
    console = Console(file=proxy)

    # If sys.stdout is a tty, console.is_terminal should be True
    # But currently it only checks for .isatty() method on the file object
    print(f"sys.stdout isatty: {sys.stdout.isatty()}")
    print(f"console.is_terminal: {console.is_terminal}")

    if sys.stdout.isatty():
        assert console.is_terminal, "console.is_terminal should be True when underlying file is a tty"
    else:
        print("sys.stdout is not a tty, skipping assertion")

