from typing import Any, Union, Annotated, get_origin, get_args
from pydantic import BaseModel

def _annotation_is_complex_mock(annotation):
    return isinstance(annotation, type) and issubclass(annotation, BaseModel)

def field_annotation_is_complex_original(annotation):
    origin = get_origin(annotation)
    if origin is Union:
        return any(field_annotation_is_complex_original(arg) for arg in get_args(annotation))
    return _annotation_is_complex_mock(annotation) or _annotation_is_complex_mock(origin)

def field_annotation_is_complex_fixed(annotation):
    origin = get_origin(annotation)
    if origin is Union:
        return any(field_annotation_is_complex_fixed(arg) for arg in get_args(annotation))
    if origin is Annotated:
        return field_annotation_is_complex_fixed(get_args(annotation)[0])
    return _annotation_is_complex_mock(annotation) or _annotation_is_complex_mock(origin)

class MyModel(BaseModel):
    pass

# Case 1: Simple model
print(f"Simple model: {field_annotation_is_complex_original(MyModel)} (Expected: True)")
print(f"Simple model fixed: {field_annotation_is_complex_fixed(MyModel)} (Expected: True)")

# Case 2: Annotated model
T2 = Annotated[MyModel, "meta"]
print(f"Annotated model: {field_annotation_is_complex_original(T2)} (Expected: False)")
print(f"Annotated model fixed: {field_annotation_is_complex_fixed(T2)} (Expected: True)")

# Case 3: Union of models
T3 = Union[MyModel, int]
print(f"Union of models: {field_annotation_is_complex_original(T3)} (Expected: True)")
print(f"Union of models fixed: {field_annotation_is_complex_fixed(T3)} (Expected: True)")

# Case 4: Annotated Union of models
T4 = Annotated[Union[MyModel, int], "meta"]
print(f"Annotated Union: {field_annotation_is_complex_original(T4)} (Expected: False)")
print(f"Annotated Union fixed: {field_annotation_is_complex_fixed(T4)} (Expected: True)")

# Case 5: Nested Annotated
T5 = Annotated[Annotated[MyModel, "m1"], "m2"]
print(f"Nested Annotated: {field_annotation_is_complex_original(T5)} (Expected: False)")
print(f"Nested Annotated fixed: {field_annotation_is_complex_fixed(T5)} (Expected: True)")

# Case 6: Annotated Union of Annotated models (The problem case)
T6 = Annotated[Annotated[MyModel, "m1"] | Annotated[MyModel, "m2"], "meta"]
# Note: | is Union in Python 3.10+
print(f"Problem case: {field_annotation_is_complex_original(T6)} (Expected: False)")
print(f"Problem case fixed: {field_annotation_is_complex_fixed(T6)} (Expected: True)")

