app = FastAPI()

@app.post("/upload_form_then_file")
async def upload_form_then_file(form_data: str = Form(...), file: UploadFile = File(...)):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload_file_then_form")
async def upload_file_then_form(file: UploadFile = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_form_then_file():
    print("Testing Form then File...")
    response = client.post(
        "/upload_form_then_file",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"Response: {response.status_code}, Body: {response.json() if response.status_code == 200 else response.text}")
    assert response.status_code == 200

def test_file_then_form():
    print("Testing File then Form...")
    response = client.post(
        "/upload_file_then_form",
        data={"form_data": "test value"},
        files={"file": ("test.txt", b"test content")}
    )
    print(f"Response: {response.status_code}, Body: {response.json() if response.status_code == 200 else response.text}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("test_form_then_file passed!")
        test_file_then_form()
        print("test_file_then_form passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import sys
        sys.exit(1)

