from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, computed_field
from fastapi.openapi.utils import get_openapi

app = FastAPI(separate_input_output_schemas=False)

class Item(BaseModel):
    name: str

    @computed_field
    @property
    def description(self) -> str:
        return f"Description of {self.name}"

@app.get("/items", response_model=Item)
def read_item():
    return Item(name="test")

client = TestClient(app)

def test_openapi_computed_field():
    openapi_schema = get_openapi(app, app.openapi_url)
    # The schema for Item should be in components/schemas
    item_schema = openapi_schema["components"]["schemas"]["Item"]
    print(f"Item schema properties: {item_schema['properties'].keys()}")
    assert "description" in item_schema["properties"], "Computed field 'description' should be in the OpenAPI schema"

if __name__ == "__main__":
    try:
        test_openapi_computed_field()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

