from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

@app.post("/upload_1")
async def upload_1(
    form_data: Annotated[str, Form()],
    file: Annotated[UploadFile, File()],
):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload_2")
async def upload_2(
    file: Annotated[UploadFile, File()],
    form_data: Annotated[str, Form()],
):
    return {"form_data": form_data, "file": file.filename}

@app.post("/upload_3")
async def upload_3(
    form_data: Annotated[str, Form()],
    file1: Annotated[UploadFile, File()],
    file2: Annotated[UploadFile, File()],
):
    return {"form_data": form_data, "file1": file1.filename, "file2": file2.filename}

@app.post("/upload_4")
async def upload_4(
    file1: Annotated[UploadFile, File()],
    file2: Annotated[UploadFile, File()],
    form_data: Annotated[str, Form()],
):
    return {"form_data": form_data, "file1": file1.filename, "file2": file2.filename}

client = TestClient(app)

def test_upload_1():
    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/upload_1", data=data, files=files)
    print(f"upload_1 status: {response.status_code}")
    assert response.status_code == 200

def test_upload_2():
    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/upload_2", data=data, files=files)
    print(f"upload_2 status: {response.status_code}")
    assert response.status_code == 200

def test_upload_3():
    files = {"file1": ("filename1", "content1"), "file2": ("filename2", "content2")}
    data = {"form_data": "some data"}
    response = client.post("/upload_3", data=data, files=files)
    print(f"upload_3 status: {response.status_code}")
    assert response.status_code == 200

def test_upload_4():
    files = {"file1": ("filename1", "content1"), "file2": ("filename2", "content2")}
    data = {"form_data": "some data"}
    response = client.post("/upload_4", data=data, files=files)
    print(f"upload_4 status: {response.status_code}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_upload_1()
        print("test_upload_1 passed")
    except Exception as e:
        print(f"test_upload_1 failed: {e}")

    try:
        test_upload_2()
        print("test_upload_2 passed")
    except Exception as e:
        print(f"test_upload_2 failed: {e}")

    try:
        test_upload_3()
        print("test_upload_3 passed")
    except Exception as e:
        print(f"test_upload_3 failed: {e}")

    try:
        test_upload_4()
        print("test_upload_4 passed")
    except Exception as e:
        print(f"test_upload_4 failed: {e}")

from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/upload_1")
async def upload_1(form_data: str = Form(...), file: bytes = File(...)):
    return {"form_data": form_data, "file_len": len(file)}

@app.post("/upload_2")
async def upload_2(file: bytes = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file_len": len(file)}

@app.post("/upload_3")
async def upload_3(form_data: str = Form(...), file1: bytes = File(...), file2: bytes = File(...)):
    return {"form_data": form_data, "file1_len": len(file1), "file2_len": len(file2)}

@app.post("/upload_4")
async def upload_4(file1: bytes = File(...), file2: bytes = File(...), form_data: str = Form(...)):
    return {"form_data": form_data, "file1_len": len(file1), "file2_len": len(file2)}

