    cases = [
        (async_func, True, "async function"),
        (sync_func, False, "sync function"),
        (wrap_async(sync_func), True, "async wrapper around sync function"),
        (wrap_sync(async_func), True, "sync wrapper around async function"),
        (partial(async_func), True, "partial of async function"),
        (partial(wrap_async(sync_func)), True, "partial of async wrapper"),
        (wrap_async(partial(async_func)), True, "async wrapper around partial of async function"),
        (AsyncCallable(), True, "async callable instance"),
        (SyncCallable(), False, "sync callable instance"),
        (wrap_async(AsyncCallable()), True, "async wrapper around async callable instance"),
        (wrap_sync(AsyncCallable()), True, "sync wrapper around async callable instance"),
        (partial(AsyncCallable()), True, "partial of async callable instance"),
