import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

if sys.version_info >= (3, 13):
    from inspect import iscoroutinefunction
else:
    from asyncio import iscoroutinefunction

import sys

async def async_func():
    return "hello"

def sync_func():
    return "hello"

def sync_wrapper(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def async_wrapper(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs) if iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapper

class CallableClass:
    def __call__(self):
        return "hello"

class AsyncCallableClass:
    async def __call__(self):
        return "hello"

def test_is_coroutine_callable():
    test_cases = [
        ("sync_func", sync_func, False),
        ("async_func", async_func, True),
        ("sync_wrapper(sync_func)", sync_wrapper(sync_func), False),
        ("sync_wrapper(async_func)", sync_wrapper(async_func), True),
        ("async_wrapper(sync_func)", async_wrapper(sync_func), True),
        ("async_wrapper(async_func)", async_wrapper(async_func), True),
        ("partial(sync_func)", partial(sync_func), False),
        ("partial(async_func)", partial(async_func), True),
        ("partial(sync_wrapper(async_func))", partial(sync_wrapper(async_func)), True),
        ("sync_wrapper(partial(async_func))", sync_wrapper(partial(async_func)), True),
        ("CallableClass", CallableClass(), False),
        ("AsyncCallableClass", AsyncCallableClass(), True),
        ("partial(AsyncCallableClass)", partial(AsyncCallableClass()), True),
    ]

    for name, call, expected in test_cases:
        dep = Dependant(call=call)
        result = dep.is_coroutine_callable
        print(f"{name}: expected {expected}, got {result} {'✅' if result == expected else '❌'}")

if __name__ == "__main__":
    test_is_coroutine_callable()

