from fastapi import FastAPI, Depends, Security
from fastapi.security import OAuth2PasswordBearer
from fastapi.openapi.utils import get_openapi_path
from fastapi.dependencies.utils import get_flat_dependant
from fastapi.dependencies.models import Dependant
import pytest

auth_scheme = OAuth2PasswordBearer(tokenUrl="token")

def dep_with_scopes():
    pass

def dep_without_scopes():
    pass

def security_dep():
    pass

# This is a security dependency without its own scopes
# It will use parent scopes if any
security_dep_with_scheme = Security(auth_scheme)

def parent_with_scopes():
    # This dependency has scopes
    return Security(auth_scheme, scopes=["read"])

def parent_without_scopes():
    # This dependency has no scopes
    return Security(auth_scheme)

def endpoint_1():
    # Parent with scopes, sub-dependency security scheme without scopes
    return Depends(parent_with_scopes), Depends(security_dep_with_scheme)

def endpoint_2():
    # Parent without scopes, sub-dependency security scheme without scopes
    return Depends(parent_without_scopes), Depends(security_dep_with_scheme)

app = FastAPI()

@app.get("/endpoint1")
def route1():
    return endpoint_1()

@app.get("/endpoint2")
def route2():
    return endpoint_2()

def test_openapi_scopes():
    # We want to check if the security requirements for endpoint1 are correct
    # when endpoint2 is also present.

    # In a real FastAPI app, the OpenAPI is generated by iterating over all routes.
    # Let's simulate that.

    # We need to mock the route objects
    from fastapi.routing import APIRoute

    # This is a bit complex to mock perfectly, so let's just use the app
    # and see what the openapi() method produces.

    openapi_schema = app.openapi()
    paths = openapi_schema["paths"]

    # Endpoint 1 should have scopes ["read"] (from parent_with_scopes) 
    # and [] (from security_dep_with_scheme, but it should be merged)
    # Actually, security_dep_with_scheme is a direct dependency of endpoint_1.
    # parent_with_scopes is also a direct dependency.
    # Both use auth_scheme.
    # So endpoint_1 should have security: [{"OAuth2PasswordBearer": ["read"]}]

    # Endpoint 2 should have security: [{"OAuth2PasswordBearer": []}]

    e1_security = paths["/endpoint1"]["get"]["security"]
    e2_security = paths["/endpoint2"]["get"]["security"]

    print(f"Endpoint 1 security: {e1_security}")
    print(f"Endpoint 2 security: {e2_security}")

    assert e1_security == [{"OAuth2PasswordBearer": ["read"]}]
    assert e2_security == [{"OAuth2PasswordBearer": []}]

if __name__ == "__main__":
    try:
        test_openapi_scopes()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
        import traceback
        traceback.print_exc()

