import inspect
import asyncio
from functools import wraps

async def foo():
    return 1

@wraps(foo)
def wrapper():
    return foo()

print(f"foo is coroutine: {asyncio.iscoroutinefunction(foo)}")
print(f"wrapper is coroutine: {asyncio.iscoroutinefunction(wrapper)}")
print(f"unwrap(wrapper) is coroutine: {asyncio.iscoroutinefunction(inspect.unwrap(wrapper))}")

class A:
    async def __call__(self):
        return 1

@wraps(A.__call__)
def wrapped_call(self):
    return A.__call__(self)

A.__call__ = wrapped_call
a = A()

print(f"a.__call__ is coroutine: {asyncio.iscoroutinefunction(a.__call__)}")
print(f"unwrap(a.__call__) is coroutine: {asyncio.iscoroutinefunction(inspect.unwrap(a.__call__))}")

